  '/api/mobile/v1/status',
  '/api/mobile/v1/connection-info',
  '/api/mobile/v1/tunnel',
  '/api/mobile/v1/p2p/rendezvous',
  '/api/mobile/v1/push-token',
  '/api/mobile/v1/perf-trace',
  '/api/mobile/v1/notification-prefs',
