const V = PERMISSIONS;
const MAP = Object.freeze({
  // ── view：只读观察 ──────────────────────────────────────────────
  '/api/mobile/v1/sessions': V.VIEW,
  '/api/mobile/v1/monitor': V.VIEW,
  '/api/mobile/v1/session': V.VIEW,
  '/api/mobile/v1/session/messages': V.VIEW,
